import sys
from math import ceil, log2

class LazySegmentTree:
    def __init__(self, size):
        self.size = size
        self.tree = [0] * (4 * size)
        self.lazy = [0] * (4 * size)

    def _update_range(self, node, start, end, l, r, value):
        if self.lazy[node] != 0:
            self.tree[node] = (end - start + 1) * self.lazy[node]
            if start != end:
                self.lazy[node * 2] = self.lazy[node]
                self.lazy[node * 2 + 1] = self.lazy[node]
            self.lazy[node] = 0

        if start > end or start > r or end < l:
            return

        if start >= l and end <= r:
            self.tree[node] = (end - start + 1) * value
            if start != end:
                self.lazy[node * 2] = value
                self.lazy[node * 2 + 1] = value
            return

        mid = (start + end) // 2
        self._update_range(node * 2, start, mid, l, r, value)
        self._update_range(node * 2 + 1, mid + 1, end, l, r, value)
        self.tree[node] = self.tree[node * 2] + self.tree[node * 2 + 1]

    def update_range(self, l, r, value):
        self._update_range(1, 0, self.size - 1, l, r, value)

    def _query_range(self, node, start, end, l, r):
        if start > end or start > r or end < l:
            return 0

        if self.lazy[node] != 0:
            self.tree[node] = (end - start + 1) * self.lazy[node]
            if start != end:
                self.lazy[node * 2] = self.lazy[node]
                self.lazy[node * 2 + 1] = self.lazy[node]
            self.lazy[node] = 0

        if start >= l and end <= r:
            return self.tree[node]

        mid = (start + end) // 2
        left_sum = self._query_range(node * 2, start, mid, l, r)
        right_sum = self._query_range(node * 2 + 1, mid + 1, end, l, r)
        return left_sum + right_sum

    def query_range(self, l, r):
        return self._query_range(1, 0, self.size - 1, l, r)

def main():
    input = sys.stdin.read
    data = input().split()

    index = 0
    N = int(data[index])
    Q = int(data[index + 1])
    index += 2

    segment_tree = LazySegmentTree(N)

    results = []

    for _ in range(Q):
        query_type = int(data[index])
        if query_type == 1:
            L = int(data[index + 1]) - 1
            R = int(data[index + 2]) - 1
            A = int(data[index + 3])
            B = int(data[index + 4])
            index += 5

            for i in range(L, R + 1):
                value = ((i - L + 1) * A) % B
                segment_tree.update_range(i, i, value)

        elif query_type == 2:
            L = int(data[index + 1]) - 1
            R = int(data[index + 2]) - 1
            index += 3

            total_stones = segment_tree.query_range(L, R)
            results.append(total_stones)

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
